def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    for r in range(h):
        for c in range(w):
            if g[r][c]!=0: continue
            if r<2: g[r][c]=1
            elif r==2: g[r][c]=4
            elif c<2: g[r][c]=1
            elif c==2: g[r][c]=4
            else:
                # Interior is a row-wise five-cell repeating sequence. Infer each
                # residue from the observed cells in this row.
                # Anchor on the long regular run at the right side of each row.
                anchors=[k for k in range(c+1,w-4) if all(grid[r][j]!=0 for j in range(k,k+5))]
                if anchors:
                    k=anchors[-1]
                    g[r][c]=grid[r][k+((c-k)%5)]
                else:
                    candidates=[grid[r][k] for k in range(3,w) if grid[r][k]!=0 and (k-c)%5==0]
                    if candidates: g[r][c]=candidates[-1]
                else:
                    # infer phase from another row: sequence advances with row
                    for rr in range(h):
                        k=next((k for k in range(3,w) if grid[rr][k]!=0 and (k-c)%5==0),None)
                        if k is not None:
                            g[r][c]=grid[rr][k]; break
    return g
